<?php
add_filter('pre_wp_mail',function($r,$a){update_option('pelham_qa_mail',$a);return true;},10,2);
add_action('wp_ajax_pelham_qa_offer',function(){if(!current_user_can('manage_options'))wp_die('',403);wp_send_json(['release'=>get_option('pelham_offer_release'),'mail'=>get_option('pelham_qa_mail'),'levels'=>pelham_ltl_levels()]);});
add_action('wp_ajax_pelham_qa_reset',function(){if(!current_user_can('manage_options'))wp_die('',403);global $wpdb;$wpdb->query("DELETE FROM {$wpdb->options} WHERE option_name LIKE 'pelham_enquiry_lock_%' OR option_name LIKE '_transient_pelham_rate_%' OR option_name LIKE '_transient_timeout_pelham_rate_%'");wp_send_json_success();});
add_action('wp_ajax_pelham_qa_reapply',function(){if(!current_user_can('manage_options'))wp_die('',403);$result=pelham_apply_offer();$checks=[];foreach(pelham_offer_entries() as $e){$p=$e['route']==='home'?get_post((int)get_option('page_on_front')):get_posts(['post_type'=>$e['type'],'name'=>basename($e['route']),'numberposts'=>1])[0];$checks[$e['route']]=['backup'=>(bool)get_post_meta($p->ID,'pelham_before_offer_1_9',true),'matches'=>pelham_18_signature($p->post_content)===pelham_18_signature($e['content'])];}wp_send_json(['result'=>!is_wp_error($result),'checks'=>$checks]);});
